eCode":{"@listName":"language","#text":"FRA"},"cac:ContractingParty":{"cbc:BuyerProfileURI":"https://www.marches-publics.gouv.fr/entreprise","cac:ContractingPartyType":{"cbc:PartyTypeCode":{"@listName":"buyer-legal-type","#text":"body-pl"}},"cac:ContractingActivity":{"cbc:ActivityTypeCode":{"@listName":"authority-activity","#text":"soc-pro"}},"cac:Party":{"cac:PartyIdentification":{"cbc:ID":"ORG-0001"}}},"cac:TenderingTerms":{"cac:ProcurementLegislationDocumentReference":[{"cbc:ID":"LocalLegalBasis","cbc:DocumentDescription":{"@languageID":"FRA","#text":"Sans objet"}},{"cbc:ID":"CrossBorderLaw","cbc:DocumentDescription":{"@languageID":"FRA","#text":"Sans objet"}}],"cac:TendererQualificationRequest":[{"cac:SpecificTendererRequirement":{"cbc:TendererRequirementTypeCode":{"@listName":"exclusion-grounds-source","#text":"epo-notice"}}},{"cac:SpecificTendererRequirement":{"cbc:TendererRequirementTypeCode":{"@listName":"exclusion-ground","#text":"exg-sitn-as-susp"}}}]},"cac:TenderingProcess":{"cbc:Description":{"@languageID":"FRA","#text":"La procédure de passation utilisée est : la procédure avec négociation. Elle est soumise aux dispositions articles L.2124-3, R. 2124-3 3°, et R. 2161-12 à R. 2161-23 du Code de la commande publique.La procédure avec négociation comprend deux (2) phases : -\tla phase de sélection des candidatures (phase 1) objet de la présente consultation ; -\tla phase de sélection des offres (phase 2). La phase 1 est consacrée à la sélection des candidatures sur la base des renseignements et documents exigés à l’article 5.3.1 du présent Règlement de Consultation ainsi que les critères de selection à l’article 5.3.3 du présent Règlement de la consultation. Les éléments fournis dans le dossier dématérialisé « candidature » des candidats permettront la sélection des candidatures et la désignation des candidats admis à présenter une offre pour la phase 2. Il est prévu une limitation du nombre de cinq (5) candidats admis à présenter une offre en phase de sélection des offres. La phase 2 est consacrée à la sélection de l’offre techniquement et économiquement la plus avantageuse sur la base des critères définis à l’article 6.3 du présent Règlement de consultation. A l’occasion de cette phase, la CPCAM a la possibilité de négocier avec l’ensemble des candidats admis à déposer une offre. La négociation n’est pas une obligation, la CPCAM se réserve également la possibilité d’attribuer le marché sur la base des offres initiales."},"cbc:ProcedureCode":{"@listName":"procurement-procedure-type","#text":"neg-w-call"},"cac:ProcessJustification":{"cbc:ProcessReasonCode":{"@listName":"accelerated-procedure","#text":"false"}}},"cac:ProcurementProject":{"cbc:ID":"26-747-08","cbc:Name":{"@languageID":"FRA","#text":"PAN 26.747.08 - MISSION DE MAITRISE D'OEUVRE RELATIVE A L'OPERATION DE RENOVATION ENERGETIQUE ET ADAPTATION DES USAGES (CREATION AGENCE) SUR LE SITE DE LA ROSE DE LA CPCAM DES BOUCHES DU RHONE"},"cbc:Description":{"@languageID":"FRA","#text":"PAN 26.747.08 - MISSION DE MAITRISE D’OEUVRE RELATIVE A L’OPÉRATION DE RÉNOVATION ENERGETIQUE ET ADAPTATION DES USAGES (CRÉATION AGENCE) SUR LE SITE DE LA ROSE DE LA CPCAM DES BOUCHES DU RHÔNE"},"cbc:ProcurementTypeCode":{"@listName":"contract-nature","#text":"services"},"cbc:Note":{"@languageID":"FRA","#text":"L'attention des candidats est portée sur le fait que la procédure est passée par la CPCAM des Bouches du Rhône, qui n'est pas un organisme de droit public mais un organisme de droit privé chargé d'une mission de service public."},"cac:RequestedTenderTotal":{"cbc:EstimatedOverallContractAmount":{"@currencyID":"EUR","#text":"270000"}},"cac:MainCommodityClassification":{"cbc:ItemClassificationCode":{"@listName":"cpv","#text":"71221000"}},"cac:RealizedLocation":{"cbc:Description":{"@languageID":"FRA","#text":"L'attention des candidats est portée sur le fait que la procédure est passée par la CPCAM des Bouches du Rhône, qui n'est pas un organisme de droit public mais un organisme de droit privé chargé d'une mission de service public."},"cac:Address":{"cbc:StreetName":"72 traverse des bonnets","cbc:CityName":"Marseille","cbc:PostalZone":"13013","cbc:CountrySubentityCode":{"@listName":"nuts","#text":"FRL04"},"cac:Country":{"cbc:IdentificationCode":{"@listName":"country","#text":"FRA"}}}}},"cac:ProcurementProjectLot":{"cbc:ID":{"@schemeName":"Lot","#text":"LOT-0001"},"cac:TenderingTerms":{"ext:UBLExtensions":{"ext:UBLExtension":{"ext:ExtensionContent":{"efext:EformsExtension":{"efac:SelectionCriteria":{"cbc:TendererRequirementTypeCode":{"@listName":"selection-criterion","#text":"slc-abil-ref-services"},"cbc:Description":{"@languageID":"FRA","#text":"La pertinence des références est appréciée au regard de leur caractère « comparable » à la « taille, nature et complexité » de l’opération objet de la présente consultation. Pour rappel, le projet concerne un ERP type U (établissement sanitaire) de 5° catégorie, qui intègre des bureaux et un laboratoire d’analyses médicales. L’ensemble des données nécessaires à l’appréciation du projet dans toutes ses dimensions figure dans le programme, pièce du DCE. Pour chaque item présenté le candidat doit fournir une seule référence en lien avec les problématiques rencontrées par le projet et doit justifier son choix (une référence peut couvrir plusieurs items)."},"efbc:SecondStageIndicator":"true"}}}}},"cbc:VariantConstraintCode":{"@listName":"permission","#text":"not-allowed"},"cbc:FundingProgramCode":{"@listName":"eu-funded","#text":"no-eu-funds"},"cbc:RecurringProcurementIndicator":"false","cac:CallForTendersDocumentReference":{"cbc:ID":"Sans objet","cbc:DocumentType":"non-restricted-document","cac:Attachment":{"cac:ExternalReference":{"cbc:URI":"https://www.marches-publics.gouv.fr/entreprise/consultation/3031929?orgAcronyme=s7h"}}},"cac:PaymentTerms":{"cbc:Note":{"@languageID":"FRA","#text":"Les prestations seront financées selon les modalités suivantes : Le financement du marché est assuré par les fonds propres de la Caisse Primaire Centrale d'Assurance Maladie des Bouches-du-Rhône. Les sommes dues au(x) titulaire(s) et au(x) sous-traitant(s) de premier rang éventuel(s) du marché seront payées dans un délai global de 30 jours à compter de la date de réception des factures ou des demandes de paiement équivalentes. Les modalités de versement des avances figurent au CCP, pièce du DCE."}},"cac:TendererQualificationRequest":[{"cac:SpecificTendererRequirement":{"cbc:TendererRequirementTypeCode":{"@listName":"selection-criteria-source","#text":"epo-notice"}}},{"cac:SpecificTendererRequirement":[{"cbc:TendererRequirementTypeCode":{"@listName":"reserved-procurement","#text":"none"}},{"cbc:TendererRequirementTypeCode":{"@listName":"reserved-procurement","#text":"none"}}]}],"cac:ContractExecutionRequirement":[{"cbc:ExecutionRequirementCode":{"@listName":"reserved-execution","#text":"no"}},{"cbc:ExecutionRequirementCode":{"@listName":"conditions","#text":"performance"}},{"cbc:ExecutionRequirementCode":{"@listName":"einvoicing","#text":"required"}},{"cbc:ExecutionRequirementCode":{"@listName":"ecatalog-submission","#text":"not-allowed"}}],"cac:AwardingTerms":{"cbc:NoFurtherNegotiationIndicator":"true","cac:AwardingCriterion":{"cac:SubordinateAwardingCriterion":[{"cbc:AwardingCriterionTypeCode":{"@listName":"award-criterion-type","#text":"quality"},"cbc:Name":{"@languageID":"FRA","#text":"Référence en site occupé 30%"},"cbc:Description":{"@languageID":"FRA","#text":"Référence en site occupé : Pertinence de la référence présentée, capacité de gestion du site occupé"}},{"cbc:AwardingCriterionTypeCode":{"@listName":"award-criterion-type","#text":"quality"},"cbc:Name":{"@languageID":"FRA","#text":"Référence Travaux, à phasages complexes : 30%"},"cbc:Description":{"@languageID":"FRA","#text":"Référence Travaux, à phasages complexes : Pertinence de la référence présentée au regard des hypothèses et scenarios de phasage et phasage travaux (planification spatiale, synoptique ...) : Explication de la complexité du phasage solutions apportées à la problématique…"}},{"cbc:AwardingCriterionTypeCode":{"@listName":"award-criterion-type","#text":"quality"},"cbc:Name":{"@languageID":"FRA","#text":"Référence contribution environnementale au projet : 15 %"},"cbc:Description":{"@languageID":"FRA","#text":"Référence contribution environnementale au projet : Pertinence de la référence présentée au regard des solutions mises en œuvre pour la résolution de problématiques d’ordre environnemental."}},{"cbc:AwardingCriterionTypeCode":{"@listName":"award-criterion-type","#text":"quality"},"cbc:Name":{"@languageID":"FRA","#text":"Référence performance thermique : 15%"},"cbc:Description":{"@languageID":"FRA","#text":"Référence performance thermique : Pertinence de la référence présentée au regard des solutions mises en œuvre pour le traitement des problématiques thermiques statiques et dynamiques."}},{"cbc:AwardingCriterionTypeCode":{"@listName":"award-criterion-type","#text":"quality"},"cbc:Name":{"@languageID":"FRA","#text":"Capacité opérationnelle à fournir une maquette bim : 10 %"},"cbc:Description":{"@languageID":"FRA","#text":"Capacité opérationnelle à fournir une maquette bim : Au regard d’un exemple concret et capacité à faire évoluer la maquette vers du bim GEM : (maitrise des outils appliqués aux maquettes numériques et application vers la maintenance et l »exploitation…)."}}]}},"cac:AdditionalInformationParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0001"}},"cac:DocumentProviderParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0001"}},"cac:TenderRecipientParty":{"cbc:EndpointID":"https://www.marches-publics.gouv.fr/entreprise/consultation/3031929?orgAcronyme=s7h","cac:PartyIdentification":{"cbc:ID":"ORG-0001"}},"cac:TenderEvaluationParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0001"}},"cac:AppealTerms":{"cac:PresentationPeriod":{"cbc:Description":{"@languageID":"FRA","#text":"Sur le fondement des articles 1441-1 à 1441-3 du Code de Procédure Civile, des articles 2 à 10 de l'ordonnance n°2009-515 du 7 mai 2009, articles 2 et 3 du décret n°2009-1456 du 27 novembre 2009, il existe deux types de référés en matière de marchés publics qui peuvent être actionnés par les requérants : - avant la conclusion du contrat, le référé précontractuel ; - après la notification du marché, le référé contractuel."}},"cac:AppealInformationParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0001"}},"cac:AppealReceiverParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0002"}},"cac:MediationParty":{"cac:PartyIdentification":{"cbc:ID":"ORG-0002"}}},"cac:Language":{"cbc:ID":"FRA"},"cac:PostAwardProcess":{"cbc:ElectronicOrderUsageIndicator":"true","cbc:ElectronicPaymentUsageIndicator":"true"}},"cac:TenderingProcess":{"cbc:SubmissionMethodCode":{"@listName":"esubmission","#text":"required"},"cbc:CandidateReductionConstraintIndicator":"true","cbc:GovernmentAgreementConstraintIndicator":"true","cac:InvitationSubmissionPeriod":{"cbc:StartDate":"2026-10-18+02:00"},"cac:ParticipationRequestReceptionPeriod":{"cbc:EndDate":"2026-09-18+02:00","cbc:EndTime":"16:00:00.000+02:00"},"cac:AdditionalInformationRequestPeriod":{"cbc:EndDate":"2026-09-08+02:00","cbc:EndTime":"16:00:00.000+02:00"},"cac:EconomicOperatorShortList":{"cbc:LimitationDescription":"true","cbc:MaximumQuantity":"5","cbc:MinimumQuantity":"5"},"cac:AuctionTerms":{"cbc:AuctionConstraintIndicator":"false"},"cac:FrameworkAgreement":{"cac:SubsequentProcessTenderRequirement":{"cbc:Name":"buyer-categories"}},"cac:ContractingSystem":[{"cbc:ContractingSystemTypeCode":{"@listName":"framework-agreement","#text":"none"}},{"cbc:ContractingSystemTypeCode":{"@listName":"dps-usage","#text":"none"}}]},"cac:ProcurementProject":{"cbc:ID":"26-747-08","cbc:Name":{"@languageID":"FRA","#text":"PAN 26.747.08 - MISSION DE MAITRISE D’OEUVRE RELATIVE A L’OPÉRATION DE RÉNOVATION ENERGETIQUE ET ADAPTATION DES USAGES (CRÉATION AGENCE) SUR LE SITE DE LA ROSE DE LA CPCAM DES BOUCHES DU RHÔNE"},"cbc:Description":{"@languageID":"FRA","#text":"L'ouvrage à réaliser appartient à la catégorie d'ouvrages bâtiment en réutilisation ou réhabilitation. Les missions confiées au maître d'œuvre seront les suivantes : - mission de base conformément aux dispositions des articles R. 2431-4, R. 2431-5, R. 2431-12 à R.2431-18 et R. 2431-19 à R. 2431-23 du Code de la commande publique ; - autres missions de maitrise d’œuvre : dans le cadre de ce projet de réhabilitation, les études de diagnostic (DIAG) sont confiées au maître d’œuvre. En sus de la mission de base, le maître d’œuvre réalisera également la mission Ordonnancement Pilotage Coordination (OPC) - missions complémentaires : mission de coordination des Systèmes de Sécurité Incendie (SSI) ainsi que la mission de synthèse (SYN). Dans le cadre de cette opération, les travaux consistent au réaménagement des espaces de travail, et à la mise en conformité au Décret Tertiaire de l'immeuble La ROSE, suite à la restructuration fonctionnelle des processus de traitement de la CPCAM 13 et afin de respecter les ratios de surface agents / m² et de l’objectif sobriété énergétique mis en place. Cette opération a donc 3 objectifs: - adaptation des usages (mise en place d'une agence pour l'accueil des assurés entre autres) - rénovation thermique du site - adaptions techniques et de la maintenance Du site de la ROSE de la CPAM La part de l'enveloppe financière estimée aux prestations de travaux est fixée à 2 700 000 €HT. La durée du marché court à compter de sa notification jusqu'à la décision de réception des ouvrages totale et sans réserves.La fin prévisionnelle des travaux est envisagée au 1er trimestre 2029"},"cbc:ProcurementTypeCode":{"@listName":"contract-nature","#text":"services"},"cbc:Note":{"@languageID":"FRA","#text":"Il n’y a pas de visite prévue en phase « candidature ». Une visite des lieux sera organisée avant la remise des offres.Il est rappelé que l'architecte ne peut prendre ni donner en sous-traitance la mission définie à l'alinéa 2 de l'article 3 de la loi n° 77-2 du 3 janvier 1977 sur l'architecture, conformément à l'article 37 du code de déontologie des architectes. La compétence thermique étant une tâche essentielle dans le présent projet de rénovation énergétique, cette mission ne peut être donnée en sous-traitance. La durée du marché est estimée à 36 mois. Toutefois, il est rappelé que la durée du marché court à compter de sa notification jusqu'à la décision de réception des ouvrages totale et sans réserves."},"cbc:SMESuitableIndicator":"true","cac:RequestedTenderTotal":{"cbc:EstimatedOverallContractAmount":{"@currencyID":"EUR","#text":"270000"}},"cac:MainCommodityClassification":{"cbc:ItemClassificationCode":{"@listName":"cpv","#text":"71221000"}},"cac:RealizedLocation":{"cbc:Description":{"@languageID":"FRA","#text":"Conformément aux dispositions de l'article 11 du Cahier des Clauses Particulières (CCP), le maitre d'oeuvre sera amené à se déplacer sur le site du siège social ainsi que sur le lieux d'exécution de la Rose, à la demande de la maitrise d'ouvrage. Il devra être en capacité de se déplacer sur ces deux sites selon les attentes et demandes de la CPCAM."},"cac:Address":{"cbc:StreetName":"72 traverse des bonnets","cbc:CityName":"Marseille","cbc:PostalZone":"13013","cbc:CountrySubentityCode":{"@listName":"nuts","#text":"FRL04"},"cac:Country":{"cbc:IdentificationCode":{"@listName":"country","#text":"FRA"}}}},"cac:PlannedPeriod":{"cbc:DurationMeasure":{"@unitCode":"MONTH","#text":"36"}}}}}}}
